package app

// Service coordinates persistence for the app.
type Service struct {
	store *Store
}

// Register persists a single new record via Store.Save.
func (svc *Service) Register(r Record) error {
	return svc.store.Save(r)
}

// Import bulk-loads records, persisting each one through Store.Save.
func Import(s *Store, rs []Record) error {
	for _, r := range rs {
		if err := s.Save(r); err != nil {
			return err
		}
	}
	return nil
}

package app

import "net/http"

// Server dispatches HTTP requests.
type Server struct{}

// Handle dispatches req and returns the built Response.
func (srv *Server) Handle(req *http.Request) *Response {
	_ = req
	return &Response{Status: 200}
}

// Response is an HTTP response envelope.
type Response struct {
	Status int
}

package app

import "time"

// Record is a stored domain entity.
type Record struct {
	ID        string
	CreatedAt time.Time
}

// Session tracks an authenticated login.
type Session struct {
	Token     string
	CreatedAt time.Time
}

// AuditEntry is an immutable audit-log line.
type AuditEntry struct {
	Actor     string
	Action    string
	CreatedAt time.Time
}

package app

// Store persists records.
type Store struct{}

// Save writes a single record and reports any error.
func (s *Store) Save(r Record) error {
	_ = r
	return nil
}
